/** Max profiles stored per dashboard */
export const DASHBOARD_SPEAKER_MAX_PROFILES = 60;
/** Max characters of a speaker name */
export const DASHBOARD_SPEAKER_NAME_MAX = 80;
/** Max characters of a speaker bio (plain text) */
export const DASHBOARD_SPEAKER_BIO_MAX = 600;

/** One speaker as stored in dashboard.settings.speakers; photoKey is an S3 URI in the app bucket */
export interface IDashboardSpeakerProfile {
  /** Stable slug, generated by the server when absent */
  id: string;
  /** Matches the grouping field's value, trimmed and case-folded */
  name: string;
  photoKey?: string;
  bio?: string;
}

/** The speakers key of dashboard.settings, saved with POST/PUT /v1/dashboards */
export interface IDashboardSpeakersSettings {
  /** The grouping field the profile names belong to */
  fieldId: string;
  profiles: IDashboardSpeakerProfile[];
}

/** A speaker on the public dashboard config: photoKey is replaced by a signed photoUrl */
export interface IPublicDashboardSpeaker {
  id: string;
  name: string;
  photoUrl?: string;
  bio?: string;
}

/** The speakers key of the public dashboard config */
export interface IPublicDashboardSpeakers {
  fieldId: string;
  profiles: IPublicDashboardSpeaker[];
}
